S = "Hakeem Force Academy"
QS = [
(S, "Where is the shrine of Data Ganj Bakhsh (Hazrat Ali Hujwiri) located?", ["Multan", "Lahore", "Pakpattan", "Uch Sharif"], 1,
 "Data Ganj Bakhsh, the author of Kashf-ul-Mahjoob, is buried in Lahore near Bhati Gate. His shrine is one of the most visited in Pakistan.",
 "His death anniversary (Urs) is held every year at the shrine in Lahore.", 1),
(S, "Where is the tomb of the Punjabi poet Waris Shah located?", ["Jandiala Sher Khan, Sheikhupura district", "Kasur", "Jhang", "Multan"], 0,
 "Waris Shah, author of the epic Heer Ranjha, is buried at Jandiala Sher Khan in Sheikhupura district, where he died in 1798.",
 "Waris Shah was born in Jandiala Sher Khan and wrote Heer in 1766.", 1),
(S, "Where is the Zhob River situated?", ["Balochistan", "Sindh", "Khyber Pakhtunkhwa (Swat)", "Gilgit-Baltistan"], 0,
 "The Zhob River rises in Balochistan and flows through the Zhob district, joining the Gomal River.",
 "The Gomal River later flows into the Indus River system through Dera Ismail Khan.", 1),
(S, "Where is the headquarters of the World Bank located?", ["Geneva", "New York", "Washington, D.C.", "Paris"], 2,
 "The World Bank has its headquarters in Washington, D.C., USA. It was set up in 1944 at the Bretton Woods conference.",
 "The International Monetary Fund (IMF) is also headquartered in Washington, D.C.", 1),
(S, "Where is the world's largest active volcano, Mauna Loa, located?", ["Hawaii, USA", "Japan", "Italy", "Indonesia"], 0,
 "Mauna Loa is on the Big Island of Hawaii and is regarded as the largest active volcano on Earth by volume. It erupted in November 2022 for the first time since 1984.",
 "Mount Etna in Italy is Europe's most active volcano.", 1),
(S, "The Yangtze and the Yellow River are the two longest rivers of which country?", ["India", "China", "Russia", "Japan"], 1,
 "Both the Yangtze and the Yellow River (Huang He) flow through China and empty into the sea on its east coast. The Yangtze is the longest river in Asia.",
 "The Yellow River is called the cradle of Chinese civilization.", 1),
(S, "Where was Benazir Bhutto assassinated in December 2007?", ["Karachi", "Lahore", "Liaquat Bagh, Rawalpindi", "Larkana"], 2,
 "Benazir Bhutto was killed on 27 December 2007 after addressing an election rally at Liaquat Bagh, Rawalpindi. She was attacked as she left the venue.",
 "She had been Prime Minister of Pakistan twice, in 1988-90 and 1993-96.", 1),
(S, "In which city was Pakistan's first Prime Minister, Liaquat Ali Khan, assassinated in 1951?", ["Lahore", "Rawalpindi", "Karachi", "Peshawar"], 1,
 "Liaquat Ali Khan was shot on 16 October 1951 while addressing a public meeting at Company Bagh in Rawalpindi.",
 "Company Bagh was later renamed Liaquat Bagh.", 1),
(S, "Which agreement was signed between Pakistan and India in January 1966 after the 1965 war?", ["Simla Agreement", "Tashkent Declaration", "Lahore Declaration", "Indus Waters Treaty"], 1,
 "The Tashkent Declaration was signed on 10 January 1966 by Ayub Khan and Lal Bahadur Shastri. It ended the 1965 war and restored the earlier positions.",
 "The Soviet Prime Minister Alexei Kosygin mediated the talks.", 2),
(S, "In which city was the Tashkent Declaration of 1966 signed?", ["Moscow", "Tashkent", "Samarkand", "Delhi"], 1,
 "The Tashkent Declaration was signed in Tashkent, then in the Soviet Union and now the capital of Uzbekistan.",
 "Indian Prime Minister Lal Bahadur Shastri died in Tashkent the day after the signing.", 1),
(S, "Which agreement was signed between Pakistan and India after the 1971 war?", ["Tashkent Declaration", "Simla Agreement", "Liaquat-Nehru Pact", "Lahore Declaration"], 1,
 "The Simla Agreement was signed on 2 July 1972 by Zulfikar Ali Bhutto and Indira Gandhi. It set the Line of Control in Kashmir.",
 "The Lahore Declaration followed much later, in 1999.", 1),
(S, "Where was the atomic test of Pakistan conducted on 28 May 1998?", ["Kahuta", "Chagai hills, Balochistan", "Sargodha", "Kirana Hills"], 1,
 "Pakistan carried out its first nuclear tests in the Ras Koh hills of Chagai district, Balochistan on 28 May 1998.",
 "Pakistan marks 28 May as Youm-e-Takbeer.", 1),
(S, "Where was the Battle of Khaibar fought?", ["Near Khaibar oasis north of Madinah, Arabia", "Khyber Pass, Pakistan", "Makkah", "Damascus"], 0,
 "The Battle of Khaibar was fought in 628-629 AD (7 AH) against the Jewish fortresses at the Khaibar oasis in Arabia. Hazrat Ali (RA) is famous for conquering the fort of Qamus.",
 "The Khyber Pass in Pakistan is a different place with a similar name.", 1),
(S, "Where was the first OIC summit held in 1969?", ["Lahore", "Rabat", "Jeddah", "Cairo"], 1,
 "The first Islamic Summit was held in Rabat, Morocco in September 1969 after the arson at Al-Aqsa Mosque.",
 "The second Islamic Summit was held in Lahore in 1974.", 1),
(S, "Where did the Prophet Muhammad (PBUH) receive the first revelation?", ["Cave of Thawr", "Cave of Hira", "Masjid-e-Nabawi", "Plain of Arafat"], 1,
 "The first revelation (the opening verses of Surah Al-Alaq) came in the Cave of Hira on Jabal al-Noor near Makkah.",
 "The Prophet (PBUH) was about 40 years old at that time.", 1),
(S, "Which three rivers were allotted to Pakistan under the Indus Waters Treaty of 1960?", ["Ravi, Beas and Sutlej", "Indus, Jhelum and Chenab", "Indus, Ravi and Sutlej", "Jhelum, Ravi and Beas"], 1,
 "Under the 1960 treaty the western rivers Indus, Jhelum and Chenab went to Pakistan. The eastern rivers Ravi, Beas and Sutlej went to India.",
 "The treaty was brokered by the World Bank.", 1),
(S, "Which acid is found in milk?", ["Citric acid", "Lactic acid", "Acetic acid", "Tartaric acid"], 1,
 "Sour milk contains lactic acid, formed when bacteria ferment lactose. Fresh milk is only slightly acidic.",
 "Citric acid is found in lemons and oranges.", 1),
(S, "Which military alliance was formed in 1955 by the Soviet bloc in response to NATO?", ["SEATO", "Warsaw Pact", "CENTO", "Comecon"], 1,
 "The Warsaw Pact was signed in 1955 by the USSR and its eastern European allies as a counter to NATO.",
 "The Warsaw Pact was dissolved in 1991.", 1),
(S, "Which angel will blow the trumpet (Sur) on the Day of Judgement?", ["Hazrat Jibrail (AS)", "Hazrat Mikail (AS)", "Hazrat Israfil (AS)", "Hazrat Azrail (AS)"], 2,
 "Hazrat Israfil (AS) is the angel appointed to blow the Sur to end the world and again to raise the dead.",
 "Hazrat Azrail (AS) is the angel of death.", 1),
(S, "Which angels write down the good and bad deeds of every human being?", ["Munkar and Nakir", "Kiraman Katibin", "Jibrail and Mikail", "Harut and Marut"], 1,
 "Kiraman Katibin are the two noble recording angels on a person's shoulders who write the deeds. One records good deeds and the other records bad deeds.",
 "Munkar and Nakir are the angels who question a person in the grave.", 2),
(S, "Which batsman scored 400 not out in a Test innings?", ["Matthew Hayden", "Brian Lara", "Sachin Tendulkar", "Inzamam-ul-Haq"], 1,
 "Brian Lara of the West Indies scored 400 not out against England at Antigua in 2004. It is the highest individual score in Test cricket.",
 "Matthew Hayden's 380 was the previous record before Lara's 400.", 1),
(S, "Which body regulates electronic media in Pakistan?", ["PTA", "PEMRA", "PBC", "SECP"], 1,
 "The Pakistan Electronic Media Regulatory Authority (PEMRA) regulates private television and radio channels.",
 "PEMRA was established in 2002.", 1),
(S, "Which child was the first to embrace Islam?", ["Hazrat Ali (RA)", "Hazrat Zaid bin Haritha (RA)", "Hazrat Abdullah bin Abbas (RA)", "Hazrat Hasan (RA)"], 0,
 "Hazrat Ali (RA), a boy of about ten, was the first child to accept Islam. Hazrat Khadija (RA) was the first woman and Hazrat Abu Bakr (RA) the first free adult man.",
 "Hazrat Zaid bin Haritha (RA) is often named as the first freed slave to accept Islam.", 1),
(S, "Which city has the highest population in Khyber Pakhtunkhwa?", ["Mardan", "Peshawar", "Abbottabad", "Swat (Mingora)"], 1,
 "Peshawar is the capital and the most populous city of Khyber Pakhtunkhwa.",
 "Mardan is generally the second largest city of the province.", 1),
(S, "Which city has the highest population in Punjab?", ["Faisalabad", "Lahore", "Rawalpindi", "Multan"], 1,
 "Lahore is the capital and the most populous city of Punjab, and the second largest in Pakistan.",
 "Faisalabad is the second largest city of Punjab.", 1),
(S, "Which city is known as the City of Saints (Madinat-ul-Auliya)?", ["Lahore", "Multan", "Peshawar", "Quetta"], 1,
 "Multan is called the City of Saints because of its many shrines of Sufi saints, such as Bahauddin Zakariya and Shah Rukn-e-Alam.",
 "Multan is also known as the City of Mangoes.", 1),
]
